-- ************************************** OPERATIONS.SERVICE_REQUEST
CREATE TABLE OPERATIONS.SERVICE_REQUEST
(
 SERVICE_REQUEST_ID     varchar(30) NOT NULL COMMENT 'Primary key for service request.',
 ADDRESS                string NOT NULL,
 SERVICE_LOCATION_ID    varchar(20) NOT NULL COMMENT 'Foreign key to Service Location.',
 SERVICE_CATEGORY_ID    int NOT NULL COMMENT 'Foreign key to Service Category.',
 REQUEST_CREATED_DATE   datetime NOT NULL COMMENT 'Date and time when request was created.',
 REPORT_DATE            date COMMENT 'Date when customer reported the issue.',
 SERVICE_STATUS_ID      int NOT NULL COMMENT 'Current status of service request.',
 PRIORITY_LEVEL         varchar(20) NOT NULL COMMENT 'Priority level (Low, Medium, High, Critical).',
 ISSUE_DESCRIPTION      varchar(500) COMMENT 'Description of issue or requested service.',
 TARGET_RESOLUTION_DATE date COMMENT 'Target resolution date based on SLA.',
 ACTUAL_RESOLUTION_DATE date COMMENT 'Actual resolution date.',
 ASSIGNED_EMPLOYEE_ID   varchar(20) COMMENT 'ID of employee assigned to resolve request.',

 CONSTRAINT PK_1 PRIMARY KEY ( SERVICE_REQUEST_ID ),
 CONSTRAINT FK_1 FOREIGN KEY ( SERVICE_LOCATION_ID ) REFERENCES CUSTOMER.SERVICE_LOCATION ( SERVICE_LOCATION_ID ),
 CONSTRAINT FK_2 FOREIGN KEY ( SERVICE_CATEGORY_ID ) REFERENCES CORE.SERVICE_CATEGORY ( SERVICE_CATEGORY_ID ),
 CONSTRAINT FK_3 FOREIGN KEY ( SERVICE_STATUS_ID ) REFERENCES CORE.SERVICE_STATUS ( SERVICE_STATUS_ID )
)
COMMENT = 'Transaction table for all customer service requests (leaks, breaks, new connections).';
